// MarkRemovals records what the *arr deleted, with each file's own timestamp and reason.
//
// UPDATE @@table AS lf
//
//	 SET removed_at = v.at,
//	     removal_reason = v.reason,
//	     superseded_at = CASE
//	         WHEN v.reason = @upgradeReason AND lf.superseded_at IS NULL
//	         THEN v.at ELSE lf.superseded_at END
//	FROM (VALUES
//	{{for i, r := range removals}}
//	  {{if i > 0}},{{end}} (@r.Path, @r.At::timestamptz, @r.Reason)
//	{{end}}
//	) AS v(path, at, reason)
//
// WHERE lf.path = v.path
func (l libraryFileDo) MarkRemovals(removals []model.LibraryFileRemoval, upgradeReason string) (rowsAffected int64, err error) {
	var params []interface{}

	var generateSQL strings.Builder
	params = append(params, upgradeReason)
	generateSQL.WriteString("UPDATE library_files AS lf SET removed_at = v.at, removal_reason = v.reason, superseded_at = CASE WHEN v.reason = ? AND lf.superseded_at IS NULL THEN v.at ELSE lf.superseded_at END FROM (VALUES ")
	for i, r := range removals {
		if i > 0 {
			generateSQL.WriteString(", ")
		}
		params = append(params, r.Path)
		params = append(params, r.At)
		params = append(params, r.Reason)
		generateSQL.WriteString("(?, ?::timestamptz, ?) ")
	}
	generateSQL.WriteString(") AS v(path, at, reason) WHERE lf.path = v.path ")

	var executeSQL *gorm.DB
	executeSQL = l.UnderlyingDB().Exec(generateSQL.String(), params...) // ignore_security_alert
	rowsAffected = executeSQL.RowsAffected
	err = executeSQL.Error

	return
}

// LinkRips marks the library files a rip produced.
//
// UPDATE @@table lf
//
//	 SET rip_id = r.id
//	FROM beets_items b
//	JOIN rips r ON r.release_mbid = b.mb_album_id
//
// WHERE lf.rip_id IS NULL
//
//	AND b.library_file_id = lf.id
func (l libraryFileDo) LinkRips() (rowsAffected int64, err error) {
	var generateSQL strings.Builder
	generateSQL.WriteString("UPDATE library_files lf SET rip_id = r.id FROM beets_items b JOIN rips r ON r.release_mbid = b.mb_album_id WHERE lf.rip_id IS NULL AND b.library_file_id = lf.id ")

	var executeSQL *gorm.DB
	executeSQL = l.UnderlyingDB().Exec(generateSQL.String()) // ignore_security_alert
	rowsAffected = executeSQL.RowsAffected
	err = executeSQL.Error

	return
}

// LinkSoulseekDownloads names the Soulseek download each library file came from.
//
// UPDATE @@table lf
//
//	 SET soulseek_download_id = d.id
//	FROM (SELECT DISTINCT ON (file_data_inode, file_data_size_bytes)
//	             id, file_data_inode, file_data_size_bytes
//	        FROM soulseek_downloads
//	       WHERE file_data_inode IS NOT NULL
//	       ORDER BY file_data_inode, file_data_size_bytes, finished_at) d
//
// WHERE lf.soulseek_download_id IS NULL
//
//	AND lf.file_data_inode IS NOT NULL
//	AND lf.file_data_inode = d.file_data_inode
//	AND lf.file_data_size_bytes = d.file_data_size_bytes
func (l libraryFileDo) LinkSoulseekDownloads() (rowsAffected int64, err error) {
	var generateSQL strings.Builder
	generateSQL.WriteString("UPDATE library_files lf SET soulseek_download_id = d.id FROM (SELECT DISTINCT ON (file_data_inode, file_data_size_bytes) id, file_data_inode, file_data_size_bytes FROM soulseek_downloads WHERE file_data_inode IS NOT NULL ORDER BY file_data_inode, file_data_size_bytes, finished_at) d WHERE lf.soulseek_download_id IS NULL AND lf.file_data_inode IS NOT NULL AND lf.file_data_inode = d.file_data_inode AND lf.file_data_size_bytes = d.file_data_size_bytes ")

	var executeSQL *gorm.DB
	executeSQL = l.UnderlyingDB().Exec(generateSQL.String()) // ignore_security_alert
	rowsAffected = executeSQL.RowsAffected
	err = executeSQL.Error

	return
}

